// Import React and hooks
import React, { useEffect, useState } from "react";

// Main component
function App() {

  // Store all users (array)
  const [users, setUsers] = useState([]);
  // WHY: store data from backend
  // WHAT: array of user objects

  // Store ID (manual input)
  const [id, setId] = useState("");
  // WHY: user types ID manually for update/delete

  // Store name input
  const [name, setName] = useState("");
  // WHAT: holds current name input

  // Store email input
  const [email, setEmail] = useState("");
  // WHAT: holds current email input

  // Backend API URL
  const API = "http://localhost:5000/users";

  // ================= READ =================

  // Function to fetch users
  const getUsers = async () => {

    // Send GET request to backend
    const res = await fetch(API);

    // Convert response to JSON
    const data = await res.json();

    // Save data to state
    setUsers(data);
    // WHY: updating state re-renders UI
  };

  // Run once when component loads
  useEffect(() => {
    getUsers();
  }, []);
  // WHY: [] means run only once on page load

  // ================= CREATE =================

  const addUser = async () => {

    // Check empty fields
    if (!id || !name || !email) {
      alert("Enter id, name and email");
      return;
    }

    // Send POST request to create user
    await fetch(API, {
      method: "POST", // create
      headers: {
        "Content-Type": "application/json"
      },
      // Convert JS object → JSON string
      body: JSON.stringify({ id, name, email })
    });

    // Clear inputs
    setId("");
    setName("");
    setEmail("");

    // Reload data
    getUsers();
  };

  // ================= UPDATE =================

  const updateUser = async () => {

    // Send PUT request using ID
    await fetch(`${API}/${id}`, {
      method: "PUT", // update
      headers: {
        "Content-Type": "application/json"
      },
      // Send updated data
      body: JSON.stringify({ name, email })
    });

    // Clear inputs
    setId("");
    setName("");
    setEmail("");

    // Reload users
    getUsers();
  };

  // ================= DELETE =================

  const deleteUser = async () => {

    // Send DELETE request using ID
    await fetch(`${API}/${id}`, {
      method: "DELETE"
    });

    // Clear ID field
    setId("");

    // Reload users
    getUsers();
  };

  // ================= UI =================

  return (
    <div>

      {/* Title */}
      <h2>CRUD App (Manual ID)</h2>

      {/* ID input */}
      <input
        placeholder="ID"
        value={id}
        onChange={(e) => setId(e.target.value)}
        // WHAT: get input value
        // WHY: needed for update/delete
      />

      {/* Name input */}
      <input
        placeholder="Name"
        value={name}
        onChange={(e) => setName(e.target.value)}
        // WHAT: store name
      />

      {/* Email input */}
      <input
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        // WHAT: store email
      />

      <br /><br />

      {/* Buttons */}
      <button onClick={addUser}>Add</button>
      {/* WHY: create new user */}

      <button onClick={updateUser}>Update</button>
      {/* WHY: update user using ID */}

      <button onClick={deleteUser}>Delete</button>
      {/* WHY: delete user using ID */}

      <hr />

      {/* Display users */}
      {users.map((u) => (
        <div key={u.id}>
          {u.id} - {u.name} - {u.email}
          {/* WHAT: show user data */}
        </div>
      ))}

    </div>
  );
}

// Export component
export default App;
